def service_curve(package_count, settings=None):
    """Reference central planned service, with an explicit sparse-count tail."""
    p = DEFAULT_CALIBRATION if settings is None else settings
    k = np.asarray(package_count, dtype=float)
    if np.any(~np.isfinite(k) | (k <= 0)):
        raise ValueError("Service curve requires finite positive counts")
    cut = p["service_support_max_count"]
    anchor = p["service_a_s"] + p["service_b_s"] * cut ** p["service_alpha"]
    result = np.where(k <= cut, p["service_a_s"] + p["service_b_s"] * k ** p["service_alpha"],
                      anchor * (k / cut) ** p["service_tail_gamma"])
    return float(result) if result.ndim == 0 else result

